</div><div class="modal-footer"><button type="button" class="btn btn-default" data-bs-dismiss="modal">Cerrar</button><button class="btn btn-danger" <?php echo(int)$balance['available']<1?'disabled':''; ?>>Solicitar cancelación</button></div><?php echo form_close(); ?>
<script>$(function(){var reason=$('#pc-cancellation-reason'),group=$('#pc-replacement-group'),uuid=$('#pc-replacement-uuid');function sync(){var needed=reason.val()==='01';group.toggleClass('d-none',!needed);uuid.prop('required',needed);if(!needed)uuid.val('');}reason.on('change',sync);sync();$('#payment-complement-cancel-form').appForm({closeModalOnSuccess:true,onSuccess:function(r){appAlert.success(r.message);var table=$('#payment-complements-table');if(table.length)table.appTable({reload:true});else location.reload();}});});</script>
